import { ref, onMounted, onUnmounted } from 'vue';
import * as echarts from 'echarts';
import 'echarts-gl';
import axios from 'axios';
import { API_CONFIG } from './config';
export default {
  __name: 'UserDashboard',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const genderChart = ref(null);
    const ageChart = ref(null);
    let genderChartInstance = null;
    let ageChartInstance = null;
    const renderGenderChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/gender-distribution`);
        const data = response.data;
        genderChartInstance = echarts.init(genderChart.value);
        const option = {
          tooltip: {
            trigger: 'item',
            formatter: '{a} <br/>{b}: {c} ({d}%)'
          },
          visualMap: {
            show: false,
            min: 0,
            max: Math.max(data.male_count, data.female_count),
            inRange: {
              colorLightness: [0.8, 0.3]
            }
          },
          series: [{
            name: '性别分布',
            type: 'pie',
            radius: '55%',
            roseType: 'radius',
            itemStyle: {
              color: '#c23531',
              shadowBlur: 20,
              shadowColor: 'rgba(0, 0, 0, 0.5)',
              borderRadius: 5,
              borderWidth: 2,
              borderColor: '#fff'
            },
            label: {
              color: 'rgba(0, 0, 0, 0.8)',
              formatter: '{b|{b}:} {per|{d}%}',
              rich: {
                b: {
                  fontSize: 12,
                  lineHeight: 20,
                  color: '#333'
                },
                per: {
                  color: '#333',
                  fontSize: 14,
                  fontWeight: 'bold',
                  padding: [2, 4],
                  borderRadius: 4
                }
              }
            },
            labelLine: {
              lineStyle: {
                color: 'rgba(0, 0, 0, 0.3)'
              },
              smooth: 0.2,
              length: 10,
              length2: 20
            },
            data: [{
              value: data.male_count,
              name: '男',
              itemStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{
                  offset: 0,
                  color: '#4b6cb7'
                }, {
                  offset: 1,
                  color: '#182848'
                }])
              }
            }, {
              value: data.female_count,
              name: '女',
              itemStyle: {
                color: new echarts.graphic.LinearGradient(0, 0, 0, 1, [{
                  offset: 0,
                  color: '#f857a6'
                }, {
                  offset: 1,
                  color: '#ff5858'
                }])
              }
            }],
            animationType: 'scale',
            animationEasing: 'elasticOut',
            animationDelay: function () {
              // 修正这里，移除了未使用的idx参数
              return Math.random() * 200;
            },
            emphasis: {
              itemStyle: {
                shadowBlur: 30,
                shadowOffsetX: 0,
                shadowColor: 'rgba(0, 0, 0, 0.5)'
              },
              label: {
                show: true,
                fontSize: '16',
                fontWeight: 'bold'
              }
            }
          }]
        };
        genderChartInstance.setOption(option);
      } catch (error) {
        console.error('获取性别分布数据失败:', error);
      }
    };

    // 其余代码保持不变...

    const __returned__ = {
      genderChart,
      ageChart,
      get genderChartInstance() {
        return genderChartInstance;
      },
      set genderChartInstance(v) {
        genderChartInstance = v;
      },
      get ageChartInstance() {
        return ageChartInstance;
      },
      set ageChartInstance(v) {
        ageChartInstance = v;
      },
      renderGenderChart,
      ref,
      onMounted,
      onUnmounted,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      },
      get API_CONFIG() {
        return API_CONFIG;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
